window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-424c2b798bf8ec0d"]={"versions": [{"id": "FIG-424c2b798bf8ec0d", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt im Kontext des AUTOSAR-Werkzeug-Interoperabilitätsstandards (AUTOSAR TR Interoperability of AUTOSAR Tools). Das Diagramm veranschaulicht das Prinzip der Änderungserkennung (Modification Detection) bei Modellvergleichen (Model Comparison / Differencing) anhand einer gerichteten Assoziation bzw. Referenzbeziehung zwischen zwei identifizierbaren Metaklassen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei Metaklassen-Entitäten und deren Beziehungsrelation:</p>\n<ul class=\"fig-list\"><li>Metaklasse <code>A</code> (gelb hinterlegt): Spezialisierung von <code>Identifiable</code> (<code>«Identifiable»</code> bzw. abgeleitet von Identifiable), fungiert als referenzierendes Modellelement.\n</li><li>Metaklasse <code>C</code> (hellbeige/creme hinterlegt): Spezialisierung von <code>Identifiable</code>, fungiert als referenziertes Modellelement.\n</li><li>Referenzbeziehung: Gerichteter offener Pfeil von Element <code>A</code> auf Element <code>C</code>, der eine navigierbare Referenz von <code>A</code> zu <code>C</code> darstellt.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne Ablauf- oder Zustandslogik. Die referenzierende Verknüpfung definiert die Auswertungslogik für Algorithmen zur Differenzerkennung:</p>\n<ol class=\"fig-list\"><li>Eine Hinzufügung, Entfernung oder Änderung des Referenzstrings (ShortName-Pfad) innerhalb von <code>A</code> wird als Modifikation von <code>A</code> gewertet.\n</li><li>Eine inhaltliche Änderung des referenzierten Zielelements <code>C</code> stellt keine Modifikation von <code>A</code> dar, es sei denn, der <code>shortName</code> von <code>C</code> ändert sich, wodurch der in <code>A</code> gespeicherte Referenzstring aktualisiert werden muss.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für AUTOSAR-Autorentools und Modellvergleichs-Engines bei der Implementierung von Differenzierungsalgorithmen (z. B. attributbasierter Modellvergleich oder Prüfsummen-/MD5-Berechnung auf Identifiable-Ebene):</p>\n<ul class=\"fig-list\"><li>Referenzen in AUTOSAR basieren auf dem <code>shortName</code>-Pfad gemäß Generic Structure Template.\n</li><li>Werkzeuge müssen sicherstellen, dass Änderungen an Zielobjekten nicht fälschlich als Änderung des referenzierenden Objekts propagiert werden, solange der Bezeichner/Referenzpfad unverändert bleibt.\n</li><li>Eine Umbenennung des referenzierten Elements erzwingt eine Aktualisierung der Referenzrepräsentation in allen referenzierenden Elementen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-14b9e211efe124c7", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt im Kontext des AUTOSAR-Werkzeug-Interoperabilitätsstandards (AUTOSAR TR Interoperability of AUTOSAR Tools). Das Diagramm veranschaulicht das Prinzip der Änderungserkennung (Modification Detection) bei Modellvergleichen (Model Comparison / Differencing) anhand einer gerichteten Assoziation bzw. Referenzbeziehung zwischen zwei identifizierbaren Metaklassen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei Metaklassen-Entitäten und deren Beziehungsrelation:</p>\n<ul class=\"fig-list\"><li>Metaklasse <code>A</code> (gelb hinterlegt): Spezialisierung von <code>Identifiable</code> (<code>«Identifiable»</code> bzw. abgeleitet von Identifiable), fungiert als referenzierendes Modellelement.\n</li><li>Metaklasse <code>C</code> (hellbeige/creme hinterlegt): Spezialisierung von <code>Identifiable</code>, fungiert als referenziertes Modellelement.\n</li><li>Referenzbeziehung: Gerichteter offener Pfeil von Element <code>A</code> auf Element <code>C</code>, der eine navigierbare Referenz von <code>A</code> zu <code>C</code> darstellt.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne Ablauf- oder Zustandslogik. Die referenzierende Verknüpfung definiert die Auswertungslogik für Algorithmen zur Differenzerkennung:</p>\n<ol class=\"fig-list\"><li>Eine Hinzufügung, Entfernung oder Änderung des Referenzstrings (ShortName-Pfad) innerhalb von <code>A</code> wird als Modifikation von <code>A</code> gewertet.\n</li><li>Eine inhaltliche Änderung des referenzierten Zielelements <code>C</code> stellt keine Modifikation von <code>A</code> dar, es sei denn, der <code>shortName</code> von <code>C</code> ändert sich, wodurch der in <code>A</code> gespeicherte Referenzstring aktualisiert werden muss.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für AUTOSAR-Autorentools und Modellvergleichs-Engines bei der Implementierung von Differenzierungsalgorithmen (z. B. attributbasierter Modellvergleich oder Prüfsummen-/MD5-Berechnung auf Identifiable-Ebene):</p>\n<ul class=\"fig-list\"><li>Referenzen in AUTOSAR basieren auf dem <code>shortName</code>-Pfad gemäß Generic Structure Template.\n</li><li>Werkzeuge müssen sicherstellen, dass Änderungen an Zielobjekten nicht fälschlich als Änderung des referenzierenden Objekts propagiert werden, solange der Bezeichner/Referenzpfad unverändert bleibt.\n</li><li>Eine Umbenennung des referenzierten Elements erzwingt eine Aktualisierung der Referenzrepräsentation in allen referenzierenden Elementen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-424c2b798bf8ec0d", "to": "FIG-14b9e211efe124c7", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
